import { z } from 'zod';
import { requireUser, requireRole } from '@/lib/auth';
import { json, readJson, route } from '@/lib/http';
import { searchPatientsByName } from '@/repos/patients';

// POST (not GET): the name fragment must travel in the body, never in the URL,
// because the Apache access log records every request line.
const Body = z.object({ q: z.string().trim().min(2).max(80) });

function isoDate(d: Date | string): string {
  return d instanceof Date ? d.toISOString().slice(0, 10) : String(d).slice(0, 10);
}

export const POST = route(async (req) => {
  const user = await requireUser(req);
  requireRole(user, 'practitioner');
  const { q } = Body.parse(await readJson(req));
  const rows = await searchPatientsByName(user.orgId, q, 20);
  return json({
    results: rows.map((r) => ({
      id: r.id,
      firstName: r.first_name,
      lastName: r.last_name,
      dateOfBirth: isoDate(r.date_of_birth),
    })),
  });
});
EOF
cat > tests/patient-search.test.ts <<'EOF'
import { describe, it, expect } from 'vitest';
import { call, TOKENS } from './helpers';
import { POST } from '@/app/api/patients/search/route';

const search = (token: string, q: unknown) =>
  call(POST, { method: 'POST', path: '/api/patients/search', token, body: { q } });

describe('patient search', () => {
  it('finds patients in own practice only, case-insensitively', async () => {
    const r = await search(TOKENS.rosa, 'a');
    expect(r.status).toBe(400);
    const all = await search(TOKENS.rosa, 'AV');
    expect(all.status).toBe(200);
    expect(all.json.results.length).toBeGreaterThan(0);
    expect(Object.keys(all.json.results[0]).sort()).toEqual(['dateOfBirth', 'firstName', 'id', 'lastName']);
  });
  it('does not cross practices', async () => {
    const mine = await search(TOKENS.hal, 'av');
    expect(mine.json.results.every((x: any) => x.firstName !== 'Ava')).toBe(true);
  });
  it('rejects other roles', async () => {
    expect((await search(TOKENS.ava, 'av')).status).toBe(403);
    expect((await search(TOKENS.dana, 'av')).status).toBe(403);
  });
  it('treats wildcards literally', async () => {
    expect((await search(TOKENS.rosa, '%%')).json.results).toEqual([]);
  });
});
EOF
